public static UPSPriceComponentCode findName(Name _codeName, boolean _update = false)
{
    UPSPriceComponentCode  priceComponentCode;

    priceComponentCode.selectForUpdate(_update);

    if (_codeName)
    {
        select firstonly priceComponentCode
            where priceComponentCode.Name == _codeName;
    }

    return priceComponentCode;
}

public static UPSPriceComponentCode find(RecId _recId, boolean _update = false)
{
    UPSPriceComponentCode  priceComponentCode;

    priceComponentCode.selectForUpdate(_update);

    if (_recId)
    {
        select firstonly priceComponentCode
            where priceComponentCode.RecId == _recId;
    }

    return priceComponentCode;
}

private boolean checkComponentCode()
{
    boolean ret = true;

    if (this.PriceComponent == UPSPriceComponent::BasePriceInventoryPrice ||
        this.PriceComponent == UPSPriceComponent::SalesTradeAgreement     ||
        this.PriceComponent == UPSPriceComponent::BasePricePurchasePrice  ||
        this.PriceComponent == UPSPriceComponent::BasePriceSalesPrice     ||
        this.PriceComponent == UPSPriceComponent::PurhcaseTradeAgreement  ||
        this.PriceComponent == UPSPriceComponent::RebateManagement)
    {
        UPSPriceComponentCode priceComponentCode;

        select firstonly RecId from priceComponentCode where
            priceComponentCode.PriceComponent == this.PriceComponent
                && priceComponentCode.RecId != this.RecId;

        if (priceComponentCode.RecId)
        {
            ret = checkFailed("@UnifiedPricingService:PriceComponentCodeAlreadyExistsError");
        }
    }

    return ret;
}

private boolean checkCombinationsWithAllGroup()
{
    boolean ret = true;

    if (this.MaintenanceMode == UPSPriceComponentCodeMaintenanceMode::Separate)
    {
        return true;
    }

    if (!this.HeaderPriceAttributeGroupAllEnabled)
    {
        UPSPriceComponentCodePriceAttributeGroupCombination combination;

        select firstonly RecId from combination 
            where combination.PriceComponentCode == this.RecId
                && combination.HeaderGroupAll == UPSGroupAll::All;

        if (combination.RecId)
        {
            ret = checkFailed("@UnifiedPricingService:UPSPriceComponentCodeCombinationCannotDisableHeaderAll");
        }

    }

    if (!this.LinePriceAttributeGroupAllEnabled)
    {
        UPSPriceComponentCodePriceAttributeGroupCombination combination;

        select firstonly RecId from combination
            where combination.PriceComponentCode == this.RecId
                && combination.LineGroupAll == UPSGroupAll::All;

        if (combination.RecId)
        {
            ret = checkFailed("@UnifiedPricingService:UPSPriceComponentCodeCombinationCannotDisableLineAll");
        }

    }

    return ret;
}

public boolean validateWrite()
{
    boolean ret = super();

    ret = ret && this.checkComponentCode();
    ret = ret && this.checkCombinationsWithAllGroup();

    return ret;
}

private void createGroupCombinationsOnHeaderGroupAllEnabled()
{
    UPSPriceComponentCodePriceAttributeGroupSelection   groupSelection;
    UPSPriceComponentCodePriceAttributeGroupCombination groupCombination;

    while select RecId, PriceAttributeGroup from groupSelection
        where groupSelection.PriceComponentCode == this.RecId
            && groupSelection.SourceLevel == UPSPricingAttributeSourceLevel::Line
    {
        groupCombination.PriceComponentCode                  = this.RecId;
        groupCombination.HeaderGroupAll                      = UPSGroupAll::All;
        groupCombination.LineGroupAll                        = UPSGroupAll::Group;
        groupCombination.LinePriceAttributeGroup             = groupSelection.PriceAttributeGroup;
        groupCombination.insert();
    }
}

private void createGroupCombinationsOnLineGroupAllEnabled()
{
    UPSPriceComponentCodePriceAttributeGroupSelection   groupSelection;
    UPSPriceComponentCodePriceAttributeGroupCombination groupCombination;

    while select RecId, PriceAttributeGroup from groupSelection
        where groupSelection.PriceComponentCode == this.RecId
            && groupSelection.SourceLevel == UPSPricingAttributeSourceLevel::Header
    {
        groupCombination.PriceComponentCode                  = this.RecId;
        groupCombination.HeaderGroupAll                      = UPSGroupAll::Group;
        groupCombination.HeaderPriceAttributeGroup           = groupSelection.PriceAttributeGroup;
        groupCombination.LineGroupAll                        = UPSGroupAll::All;
        groupCombination.insert();
    }
}

private void removeGroupCombinationsOnHeaderGroupAllDisabled()
{
    UPSPriceComponentCodePriceAttributeGroupCombination groupCombination;

    delete_from groupCombination
        where groupCombination.HeaderGroupAll == UPSGroupAll::All
            && groupCombination.PriceComponentCode == this.RecId;
}

private void removeGroupCombinationsOnLineGroupAllDisabled()
{
    UPSPriceComponentCodePriceAttributeGroupCombination groupCombination;

    delete_from groupCombination
        where groupCombination.LineGroupAll == UPSGroupAll::All
            && groupCombination.PriceComponentCode == this.RecId;
}

private void updateGroupCombinationsOnGroupAllChange()
{
    UPSPriceComponentCodePriceAttributeGroupCombination groupCombination;

    boolean headerAllEnabled  = !this.orig().HeaderPriceAttributeGroupAllEnabled  &&  this.HeaderPriceAttributeGroupAllEnabled;
    boolean headerAllDisabled =  this.orig().HeaderPriceAttributeGroupAllEnabled  && !this.HeaderPriceAttributeGroupAllEnabled;
    boolean lineAllEnabled    = !this.orig().LinePriceAttributeGroupAllEnabled    &&  this.LinePriceAttributeGroupAllEnabled;
    boolean lineAllDisabled   =  this.orig().LinePriceAttributeGroupAllEnabled    && !this.LinePriceAttributeGroupAllEnabled;

    // Only create combinations when header/line priorities are separately assigned.
    if (headerAllEnabled && this.MaintenanceMode == UPSPriceComponentCodeMaintenanceMode::Separate)
    {
        this.createGroupCombinationsOnHeaderGroupAllEnabled();
    }
    else if (headerAllDisabled)
    {
        this.removeGroupCombinationsOnHeaderGroupAllDisabled();
    }

    if (lineAllEnabled && this.MaintenanceMode == UPSPriceComponentCodeMaintenanceMode::Separate)
    {
        this.createGroupCombinationsOnLineGroupAllEnabled();
    }
    else if (lineAllDisabled)
    {
        this.removeGroupCombinationsOnLineGroupAllDisabled();
    }

    if ( (headerAllEnabled || lineAllEnabled) &&
            this.HeaderPriceAttributeGroupAllEnabled &&
            this.LinePriceAttributeGroupAllEnabled &&
            this.MaintenanceMode == UPSPriceComponentCodeMaintenanceMode::Separate)
    {
        // A combination with "all" for both header AND line must be inserted.
        groupCombination.PriceComponentCode         = this.RecId;
        groupCombination.HeaderGroupAll             = UPSGroupAll::All;
        groupCombination.LineGroupAll               = UPSGroupAll::All;
        groupCombination.insert();
    }
}

private void updateGroupCombinationsOnNewRecord()
{
    UPSPriceComponentCodePriceAttributeGroupCombination groupCombination;

    if (this.HeaderPriceAttributeGroupAllEnabled && this.LinePriceAttributeGroupAllEnabled)
    {
        groupCombination.PriceComponentCode         = this.RecId;
        groupCombination.HeaderGroupAll             = UPSGroupAll::All;
        groupCombination.LineGroupAll               = UPSGroupAll::All;
        groupCombination.insert();
    }
}

public void update()
{
    ttsbegin;

    this.updateGroupCombinationsOnGroupAllChange();
    super();

    ttscommit;
}

public void insert()
{
    ttsbegin;

    super();

    if (this.MaintenanceMode == UPSPriceComponentCodeMaintenanceMode::Separate)
    {
        this.updateGroupCombinationsOnNewRecord();
    }

    ttscommit;
}
